<template>
  <section class="admin-work-panel">
    <div class="admin-toolbar"><h2>{{ titles[section] }}</h2><template v-if="section === 'orders' || section === 'refunds'"><select v-model="orderFilter" aria-label="주문 상태" @change="load(1)"><option value="">전체 상태</option><option v-for="s in orderStates" :key="s.value" :value="s.value">{{ s.label }}</option></select><form @submit.prevent="load(1)"><input v-model.trim="keyword" placeholder="주문번호 또는 주문자 검색"><button>검색</button></form></template><button type="button" @click="load(1)">새로고침</button><button v-if="section === 'notices'" type="button" @click="newNotice">공지 등록</button><button v-if="section === 'coupons'" type="button" @click="newCoupon">쿠폰 등록</button></div>
    <p v-if="error" class="admin-error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><p v-if="loading" role="status">불러오는 중입니다...</p>
    <form v-if="editingNotice" class="dashboard-card admin-editor" @submit.prevent="saveNotice"><h3>{{ noticeId ? '공지 수정' : '공지 등록' }}</h3><div class="admin-fields"><label>제목<input v-model.trim="notice.title" required maxlength="250"></label><label>분류<select v-model="notice.category"><option value="GENERAL">일반</option><option value="EVENT">이벤트</option><option value="DELIVERY">배송</option><option value="SYSTEM">시스템</option></select></label><label>내용<textarea v-model.trim="notice.content" required rows="6"></textarea></label><label><input type="checkbox" v-model="notice.is_pinned"> 상단 고정</label><label><input type="checkbox" v-model="notice.is_published"> 공개</label></div><div class="admin-actions"><button :disabled="busy">저장</button><button type="button" @click="editingNotice=false">닫기</button></div></form>
    <form v-if="editingCoupon" class="dashboard-card admin-editor" @submit.prevent="saveCoupon"><h3>쿠폰 등록</h3><div class="admin-fields"><label>쿠폰 코드 (영문·숫자·밑줄·하이픈)<input v-model.trim="coupon.code" required pattern="[A-Za-z0-9_-]+" maxlength="40"></label><label>쿠폰 이름<input v-model.trim="coupon.name" required maxlength="120"></label><label>할인 방식<select v-model="coupon.coupon_type"><option value="AMOUNT">정액 할인</option><option value="PERCENT">정률 할인</option><option value="FREESHIP">무료 배송</option></select></label><label v-if="coupon.coupon_type !== 'FREESHIP'">{{ coupon.coupon_type === 'PERCENT' ? '할인율 (%)' : '할인 금액 (원)' }}<input v-model.number="coupon.discount_value" type="number" min="1" :max="coupon.coupon_type === 'PERCENT' ? 100 : 99999999" required></label><label v-if="coupon.coupon_type === 'PERCENT'">최대 할인 금액 (선택)<input v-model="coupon.max_discount" type="number" min="0"></label><label>최소 주문 금액<input v-model.number="coupon.min_order_amount" type="number" min="0" required></label><label>발급 수량 (비우면 제한 없음)<input v-model="coupon.total_quantity" type="number" min="1"></label><label>사용 종료 일시<input v-model="coupon.valid_to" type="datetime-local" required></label></div><div class="admin-actions"><button :disabled="busy">등록</button><button type="button" @click="editingCoupon=false">닫기</button></div></form>
    <div v-if="!loading" class="dashboard-card table-wrap"><table><thead><tr v-if="section === 'orders' || section === 'refunds'"><th>주문번호</th><th>주문자</th><th>결제 금액</th><th>상태</th><th>관리</th></tr><tr v-else-if="section === 'qna'"><th>제목</th><th>작성자</th><th>처리 상태</th><th>관리</th></tr><tr v-else-if="section === 'reviews'"><th>도서</th><th>작성자</th><th>리뷰</th><th>공개 상태</th><th>관리</th></tr><tr v-else-if="section === 'notices'"><th>제목</th><th>고정</th><th>게시일</th><th>관리</th></tr><tr v-else><th>쿠폰</th><th>할인</th><th>발급</th><th>종료일</th><th>상태</th><th>관리</th></tr></thead><tbody>
      <template v-for="item in items" :key="item.order_id || item.question_id || item.review_id || item.notice_id || item.coupon_id">
        <tr v-if="section === 'orders' || section === 'refunds'"><td>{{ item.order_no }}</td><td>{{ item.orderer_name }}</td><td>{{ money(item.total_amount) }}</td><td>{{ item.status_label }}</td><td><RouterLink class="admin-detail-link" :to="{name:'adminOrderDetail',params:{id:item.order_id},query:{from:section}}">상세 보기</RouterLink></td></tr>
        <tr v-else-if="section === 'qna'"><td>{{ item.title }}</td><td>{{ item.member_name }}</td><td>{{ qnaStatus(item.status) }}</td><td><button type="button" @click="openDetail(item, $event)">상세·답변</button></td></tr>
        <tr v-else-if="section === 'reviews'"><td>{{ item.book_title }}</td><td>{{ item.member_name }}</td><td class="review-preview">{{ item.rating }}점 · {{ item.content }}</td><td>{{ item.is_blinded ? '숨김' : '공개' }}</td><td><button type="button" @click="openDetail(item, $event)">상세·관리</button></td></tr>
        <tr v-else-if="section === 'notices'"><td>{{ item.title }}</td><td>{{ item.is_pinned ? '고정' : '일반' }}</td><td>{{ date(item.published_at) }}</td><td><button type="button" @click="editNotice(item)">수정</button> <button type="button" @click="deleteNotice(item)">삭제</button></td></tr>
        <tr v-else><td>{{ item.name }}<br><small>{{ item.code }}</small></td><td>{{ couponLabel(item) }}</td><td>{{ item.issued_count }} / {{ item.total_quantity ?? '제한 없음' }}</td><td>{{ date(item.valid_to) }}</td><td>{{ item.is_active ? '활성' : '중지' }}</td><td><button type="button" @click="toggleCoupon(item)">{{ item.is_active ? '중지' : '활성화' }}</button></td></tr>
      </template><tr v-if="!items.length"><td colspan="6">표시할 항목이 없습니다.</td></tr></tbody></table></div>
    <nav v-if="pages > 1" class="domestic-pagination" aria-label="목록 페이지"><button :disabled="page <= 1" @click="load(page-1)">이전</button><span>{{ page }} / {{ pages }}</span><button :disabled="page >= pages" @click="load(page+1)">다음</button></nav>
    <Teleport to="body"><dialog ref="detailDialog" class="admin-detail-dialog" aria-labelledby="admin-dialog-title" @close="onDialogClose" @cancel="onDialogCancel"><div v-if="detail" class="admin-dialog-inner"><div class="admin-dialog-top"><span>{{ section === 'qna' ? '고객 문의' : '리뷰 관리' }}</span><button type="button" class="admin-dialog-close" :disabled="busy" aria-label="상세 창 닫기" @click="closeDetail">×</button></div><p v-if="error" class="admin-error" role="alert">{{ error }}</p><section v-if="section === 'qna'" class="admin-dialog-content"><h3 id="admin-dialog-title">{{ detail.title }}</h3><p class="admin-pre">{{ detail.content || '내용을 확인할 수 없습니다.' }}</p><p v-for="answer in detail.answers" :key="answer.answer_id" class="admin-pre">답변: {{ answer.content }}</p><form v-if="detail.status !== 'CLOSED'" @submit.prevent="answerQuestion"><label>답변<textarea v-model.trim="answer" required maxlength="5000" rows="4"></textarea></label><div class="admin-actions"><button :disabled="busy">답변 등록</button><button type="button" :disabled="busy" @click="closeQuestion">문의 종료</button></div></form></section>
    <section v-if="section === 'reviews'" class="admin-dialog-content"><h3 id="admin-dialog-title">{{ detail.book_title }} · {{ detail.rating }}점</h3><p class="admin-dialog-meta">작성자 {{ detail.member_name }} · {{ date(detail.created_at) }} · {{ detail.is_blinded ? '숨김' : '공개' }}</p><p class="admin-pre">{{ detail.content }}</p><p v-if="detail.reply_content" class="admin-pre">기존 답글: {{ detail.reply_content }}</p><form @submit.prevent="replyReview"><label>답글<textarea v-model.trim="answer" required maxlength="2000" rows="4"></textarea></label><div class="admin-actions"><button :disabled="busy">답글 저장</button><button type="button" :disabled="busy" @click="blindReview">{{ detail.is_blinded ? '숨김 해제' : '리뷰 숨김' }}</button></div></form></section></div></dialog></Teleport>
  </section>
</template>

<script setup>
import { ref, watch, nextTick, onBeforeUnmount } from 'vue';
import http from '../../api/http';
const props=defineProps({section:{type:String,required:true}});
const titles={orders:'주문·배송 목록',refunds:'취소·환불 처리',qna:'고객 문의 목록',reviews:'리뷰 목록',notices:'공지사항 목록',coupons:'쿠폰 목록'};
const items=ref([]),page=ref(1),pages=ref(1),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),detail=ref(null),answer=ref(''),editingNotice=ref(false),noticeId=ref(null),editingCoupon=ref(false);
const notice=ref({}),coupon=ref({}), detailDialog=ref(null);
let lastTrigger=null;
async function openDetail(item,event){lastTrigger=event.currentTarget;detail.value=item;answer.value='';error.value='';await nextTick();detailDialog.value?.showModal()}
function closeDetail(){if(!busy.value)detailDialog.value?.close()}
function onDialogCancel(event){if(busy.value)event.preventDefault()}
function onDialogClose(){detail.value=null;answer.value='';lastTrigger?.focus();lastTrigger=null}
onBeforeUnmount(()=>{if(detailDialog.value?.open) detailDialog.value.close()});
const keyword=ref(''),orderFilter=ref('');
const orderStates=[{value:'PENDING',label:'결제 대기'},{value:'PAID',label:'결제 완료'},{value:'PREPARING',label:'상품 준비'},{value:'SHIPPING',label:'배송 중'},{value:'DELIVERED',label:'배송 완료'},{value:'CONFIRMED',label:'구매 확정'},{value:'CANCELLED',label:'주문 취소'},{value:'RETURN_REQ',label:'반품 접수'},{value:'EXCHANGE_REQ',label:'교환 접수'}];
let generation=0;
const money=n=>`${Number(n||0).toLocaleString('ko-KR')}원`,date=s=>s?new Date(s).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}):'—';
const qnaStatus=s=>({WAITING:'답변 대기',ANSWERED:'답변 완료',CLOSED:'종료'}[s] || '확인 필요');
const couponLabel=c=>c.coupon_type==='FREESHIP'?'무료 배송':c.coupon_type==='PERCENT'?`${c.discount_value}% 할인`:`${money(c.discount_value)} 할인`;
const paths={orders:'/api/v1/admin/orders',refunds:'/api/v1/admin/orders',qna:'/api/v1/qna',reviews:'/api/v1/admin/reviews',notices:'/api/v1/admin/notices',coupons:'/api/v1/admin/coupons'};
async function load(n=1){const token=++generation,section=props.section;loading.value=true;error.value='';try{const params={page:n,size:20};if(['orders','refunds'].includes(section)){if(orderFilter.value)params.status=orderFilter.value;if(keyword.value)params.keyword=keyword.value}const {data}=await http.get(paths[section],{params});if(token!==generation)return;items.value=data.items;page.value=data.meta.page;pages.value=Math.max(1,data.meta.total_pages||1)}catch(e){if(token===generation)error.value=e.userMessage||'목록을 불러오지 못했습니다.'}finally{if(token===generation)loading.value=false}}
watch(()=>props.section,()=>{detail.value=null;answer.value='';keyword.value='';orderFilter.value='';editingNotice.value=false;editingCoupon.value=false;message.value='';load()}, {immediate:true});
async function run(action,success){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await action();if(detailDialog.value?.open)detailDialog.value.close();else detail.value=null;message.value=success;await load(page.value)}catch(e){error.value=e.userMessage||'요청을 처리하지 못했습니다.'}finally{busy.value=false}}
function answerQuestion(){const value=answer.value;run(async()=>{await http.post(`/api/v1/admin/qna/${detail.value.question_id}/answer`,{content:value});answer.value=''},'답변을 등록했습니다.')}
function closeQuestion(){if(!confirm('문의를 종료하시겠습니까?'))return;run(()=>http.post(`/api/v1/admin/qna/${detail.value.question_id}/close`),'문의를 종료했습니다.')}
function replyReview(){const value=answer.value;run(async()=>{await http.post(`/api/v1/admin/reviews/${detail.value.review_id}/reply`,{reply_content:value});answer.value=''},'답글을 저장했습니다.')}
function blindReview(){if(!confirm('리뷰 공개 상태를 변경하시겠습니까?'))return;run(()=>http.post(`/api/v1/admin/reviews/${detail.value.review_id}/blind`,null,{params:{blinded:!detail.value.is_blinded}}),'리뷰 공개 상태를 변경했습니다.')}
function newNotice(){noticeId.value=null;notice.value={title:'',content:'',category:'GENERAL',is_pinned:false,is_published:true};editingNotice.value=true}
function editNotice(item){noticeId.value=item.notice_id;notice.value={title:item.title,content:item.content||'',category:item.category,is_pinned:item.is_pinned,is_published:item.is_published ?? true};editingNotice.value=true}
function saveNotice(){const id=noticeId.value,payload={...notice.value};run(async()=>{await (id?http.put(`/api/v1/admin/notices/${id}`,payload):http.post('/api/v1/admin/notices',payload));editingNotice.value=false},'공지사항을 저장했습니다.')}
function deleteNotice(item){if(!confirm(`“${item.title}” 공지를 삭제하시겠습니까?`))return;run(()=>http.delete(`/api/v1/admin/notices/${item.notice_id}`),'공지사항을 삭제했습니다.')}
function newCoupon(){coupon.value={code:'',name:'',coupon_type:'AMOUNT',discount_value:0,max_discount:'',min_order_amount:0,total_quantity:'',valid_to:''};editingCoupon.value=true}
function saveCoupon(){const c=coupon.value;const payload={...c,discount_value:c.coupon_type==='FREESHIP'?0:Number(c.discount_value),max_discount:c.coupon_type==='PERCENT' && c.max_discount!==''?Number(c.max_discount):null,total_quantity:c.total_quantity===''?null:Number(c.total_quantity),valid_to:new Date(c.valid_to).toISOString()};run(async()=>{await http.post('/api/v1/admin/coupons',payload);editingCoupon.value=false},'쿠폰을 등록했습니다.')}
function toggleCoupon(item){if(!confirm(`쿠폰을 ${item.is_active?'중지':'활성화'}하시겠습니까?`))return;run(()=>http.patch(`/api/v1/admin/coupons/${item.coupon_id}`,{is_active:!item.is_active}),'쿠폰 상태를 변경했습니다.')}
</script>

<style scoped>
.admin-work-panel textarea,.admin-work-panel select{width:100%;padding:10px;border:1px solid #ddd3e5;border-radius:6px;font:inherit}.admin-work-panel .admin-pre{white-space:pre-wrap;overflow-wrap:anywhere}.admin-work-panel td{vertical-align:top;overflow-wrap:anywhere}.admin-work-panel .admin-actions label{display:block;min-width:150px;font-size:13px}.admin-work-panel .admin-actions input,.admin-work-panel .admin-actions select{display:block;margin-top:5px}.admin-work-panel .admin-fields label:has(input[type=checkbox]){display:flex;align-items:center;gap:7px}.admin-work-panel .admin-fields input[type=checkbox]{width:auto}
.admin-detail-link{display:inline-flex;padding:9px 13px;border:1px solid #ded3ea;border-radius:8px;color:#51316e;text-decoration:none;white-space:nowrap}.review-preview{max-width:320px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.admin-detail-dialog{width:min(620px,calc(100% - 32px));max-height:min(85vh,800px);padding:0;border:0;border-radius:14px;box-shadow:0 20px 65px #24133240;color:#30263a}.admin-detail-dialog::backdrop{background:#21192bbb}.admin-dialog-inner{padding:26px}.admin-dialog-top{display:flex;align-items:center;justify-content:space-between;color:#856b9b;font-size:12px;font-weight:700}.admin-dialog-close{width:38px;height:38px;border:0;border-radius:50%;background:#f4eff8;color:#65419a;font-size:24px;cursor:pointer}.admin-dialog-content h3{margin:18px 0 12px;font-size:21px}.admin-dialog-content p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.admin-dialog-meta{color:#85798a;font-size:13px}.admin-dialog-content label{display:block;margin:20px 0 8px;font-weight:700}.admin-dialog-content textarea{display:block;box-sizing:border-box;width:100%;margin-top:8px;padding:12px;border:1px solid #ddd3e5;border-radius:8px;font:inherit}.admin-dialog-content .admin-actions{display:flex;gap:8px;margin-top:14px}.admin-dialog-content .admin-actions button{padding:10px 15px;border:1px solid #ded3ea;border-radius:8px;background:#65419a;color:white;cursor:pointer}.admin-dialog-content .admin-actions button+button{background:white;color:#65419a}.admin-error{color:#a32c2c}@media(max-width:600px){.admin-dialog-inner{padding:20px}.admin-detail-dialog{max-height:90vh}.admin-dialog-content .admin-actions{flex-wrap:wrap}}
.admin-work-panel,.admin-detail-dialog{font-size:16px;line-height:1.55}.admin-work-panel .admin-actions label,.admin-dialog-top,.admin-dialog-meta{font-size:15px}.admin-dialog-content h3{font-size:23px}.admin-dialog-content label,.admin-dialog-content textarea,.admin-dialog-content .admin-actions button,.admin-detail-link{font-size:16px}
</style>
